import java.io.BufferedOutputStream;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.StringTokenizer;

public class C
{
	static PrintWriter out = new PrintWriter(
			new BufferedOutputStream(System.out));
	static MyScanner sc = new MyScanner(System.in);
	static StringBuilder output = new StringBuilder();

	public static void main(String... args)
	{
		int a = sc.nextInt();
		int b = sc.nextInt();
		int l = sc.nextInt() - 1;
		int r = sc.nextInt();

		r -= l / (a + b) * (a + b);
		l -= l / (a + b) * (a + b);

		if (r > (a + b) * 3)
		{
			r -= r / (a + b) * (a + b);
			r += (a + b) * 3;
		}

		int[] seq = new int[r];

		for (int i = 0; i < r; i++)
		{
			seq[i] = i;
		}

		{
			int i = a;
			while (i < r)
			{
				if (i % (a + b) < a)
				{
					HashSet<Integer> used = new HashSet<Integer>();
					for (int j = i - 1; i - j <= a; j--)
					{
						used.add(seq[j]);
					}

					for (int j = 0; i % (a + b) != a && i < r; i++, j++)
					{
						while (used.contains(j))
						{
							j++;
						}
						used.add(j);

						seq[i] = j;
					}
				}
				else
				{
					seq[i] = seq[i - 1];
					i++;
				}
			}
		}

		int result;

		{
			HashSet<Integer> used = new HashSet<Integer>();

			for (int i = l; i < r; i++)
			{
				used.add(seq[i]);
			}

			result = used.size();
		}

		for(int i = a; i < a + b && i < r && b < r; i++)
		{
			seq[i] = seq[b];
		}

		{
			int i = a + b;
			while (i < r)
			{
				if (i % (a + b) < a)
				{
					HashSet<Integer> used = new HashSet<Integer>();
					for (int j = i - 1; i - j <= a; j--)
					{
						used.add(seq[j]);
					}

					for (int j = 0; i % (a + b) != a && i < r; i++, j++)
					{
						while (used.contains(j))
						{
							j++;
						}
						used.add(j);

						seq[i] = j;
					}
				}
				else
				{
					seq[i] = seq[i - 1];
					i++;
				}
			}
		}

		{
			HashSet<Integer> used = new HashSet<Integer>();

			for (int i = l; i < r; i++)
			{
				used.add(seq[i]);
			}

			result = Math.min(result, used.size());
		}



		output.append(result);


		eOP();
	}

	private static void eOP()
	{
		System.out.println(output);
		System.exit(0);
	}

	/**
	 * Flatfoot's Scanner with slight modifications.
	 * 
	 * @author <a href="http://codeforces.com/profile/Flatfoot">Flatfoot</a>
	 * @see <a href="http://codeforces.com/blog/entry/7018">Source</a>
	 */
	private static class MyScanner
	{
		BufferedReader br;
		StringTokenizer st;

		MyScanner(InputStream in)
		{
			this.br = new BufferedReader(new InputStreamReader(in));
		}

		String next()
		{
			while (this.st == null || !this.st.hasMoreElements())
			{
				try
				{
					this.st = new StringTokenizer(this.br.readLine());
				}
				catch (IOException e)
				{
					e.printStackTrace();
				}
			}
			return this.st.nextToken();
		}

		int nextInt()
		{
			return Integer.parseInt(this.next());
		}

		long nextLong()
		{
			return Long.parseLong(this.next());
		}

		double nextDouble()
		{
			return Double.parseDouble(this.next());
		}

		/**
		 * This method has been modified to be a bit more similar to Scanner's
		 * 
		 * @author <a href=
		 *         "http://codeforces.com/profile/Flatfoot">Flatfoot</a>,
		 *         <a href=
		 *         "http://codeforces.com/profile/JasonBaby">JasonBaby</a>
		 */
		String nextLine()
		{
			if (this.st == null || !this.st.hasMoreElements())
			{
				String str = "";
				try
				{
					str = this.br.readLine();
				}
				catch (IOException e)
				{
					e.printStackTrace();
				}
				return str;
			}
			else
			{
				StringBuilder str = new StringBuilder();
				while (this.st.hasMoreElements())
				{
					str.append(this.st.nextToken());
					str.append(" ");
				}
				str.deleteCharAt(str.length() - 1);
				return str.toString();
			}
		}

	}
}

